{
  // Specify the settings for the workspace webhook notification channel here.
  // See https://docs.unstructured.io/api-reference/webhooks
  // API reference: https://docs.unstructured.io/api-reference/api/notification/create-notification-channel
  "channel_type": "webhook",
  "url": "https://hooks.example.com/notify",
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "description": "Workspace job status alerts",
  "secret": "<signing-secret-24-to-75-chars>"
}

{
  // Specify the fields to update for the workspace webhook notification channel here.
  // See https://docs.unstructured.io/api-reference/webhooks
  // API reference: https://docs.unstructured.io/api-reference/api/notification/update-notification-channel
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "url": "https://hooks.example.com/notify",
  "enabled": true
}

{
  // Specify the settings for the workflow webhook notification channel here.
  // See https://docs.unstructured.io/api-reference/webhooks
  // API reference: https://docs.unstructured.io/api-reference/api/workflow/create-workflow-notification-channel
  "channel_type": "webhook",
  "url": "https://hooks.example.com/notify",
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "description": "Workflow job status alerts",
  "secret": "<signing-secret-24-to-75-chars>"
}

{
  // Specify the fields to update for the workflow webhook notification channel here.
  // See https://docs.unstructured.io/api-reference/webhooks
  // API reference: https://docs.unstructured.io/api-reference/api/workflow/update-workflow-notification-channel
  "event_types": ["job.scheduled", "job.in_progress", "job.completed", "job.stopped", "job.failed"],
  "url": "https://hooks.example.com/notify",
  "enabled": true
}

{
  // Specify exactly one of: notification_ids, before, or mark_all.
  // See https://docs.unstructured.io/api-reference/webhooks
  // API reference: https://docs.unstructured.io/api-reference/api/notification/mark-notifications-read
  "notification_ids": ["<uuid>", "<uuid>"]
  // "before": "<YYYY-MM-DDTHH:MM:SSZ>"
  // "mark_all": true
}
